<!DOCTYPE html>
<html lang="hu">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="description" content="Kvantum Fehérje Hajtogatási Rendszer - Haladó molekuláris modellezés kvantum számítástechnikával">
    <title>JADED</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
        :root {
            --primary: #0A61F7;
            --secondary: #39FF14;
            --accent: #0A61F7;
            --border-glow: rgba(10, 97, 247, 0.5);
            --primary-rgb: 10, 97, 247;
            --secondary-rgb: 57, 255, 20;
            --bg: #000000;
            --surface: rgba(10, 10, 10, 0.7);
            --glass: rgba(255, 255, 255, 0.02);
            --glass-strong: rgba(255, 255, 255, 0.05);
            --border: rgba(255, 255, 255, 0.08);
            --text: #f0f0f0;
            --text-muted: #94a3b8;
            --radius-lg: 24px;
            --radius-md: 16px;
            --radius-sm: 12px;
            --shadow: 0 12px 48px rgba(0, 0, 0, 0.6);
            --transition-curve: cubic-bezier(0.25, 0.8, 0.25, 1);
            --transition-color-slow: 15s ease-in-out;
        }
        * { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
        html { height: 100%; height: -webkit-fill-available; scroll-behavior: smooth; }
        body {
            font-family: 'Inter', sans-serif; background: var(--bg); color: var(--text);
            min-height: 100vh; min-height: -webkit-fill-available; overflow-x: hidden;
            -webkit-font-smoothing: antialiased; font-size: 15px;
        }
        .aurora-background { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; pointer-events: none; z-index: -1; overflow: hidden; will-change: transform; }
        .aurora { position: absolute; border-radius: 50%; mix-blend-mode: screen; filter: blur(120px); opacity: 0.3; transition: background-color var(--transition-color-slow), opacity 8s ease-in-out; animation: pulse 30s ease-in-out infinite alternate; will-change: transform, opacity; }
        .aurora.one { width: 80vmax; height: 80vmax; background: radial-gradient(circle, var(--primary), transparent); animation: move-one 1200s linear infinite alternate, pulse 35s ease-in-out infinite alternate; }
        .aurora.two { width: 70vmax; height: 70vmax; background: radial-gradient(circle, var(--secondary), transparent); animation: move-two 1050s linear infinite alternate, pulse 40s ease-in-out infinite alternate; }
        @keyframes move-one { from { transform: translate(-20vw, -20vh) scale(1); } to { transform: translate(50vw, 80vh) scale(1.2); } }
        @keyframes move-two { from { transform: translate(80vw, 30vh) scale(1); } to { transform: translate(-10vw, 60vh) scale(1.3); } }
        @keyframes pulse { from { opacity: 0.2; } to { opacity: 0.4; } }
        .container { display: flex; min-height: 100vh; position: relative; }
        .main-content { flex: 1; display: flex; flex-direction: column; min-height: 100vh; overflow: hidden; }
        .header {
            padding: 12px 20px; height: 64px; background: var(--surface); backdrop-filter: blur(60px) saturate(180%);
            border-bottom: 1px solid var(--border); display: flex; align-items: center; justify-content: space-between;
            position: sticky; top: 0; z-index: 100;
        }
        .header-title {
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            -webkit-background-clip: text; -webkit-text-fill-color: transparent;
            text-shadow: 0 0 15px var(--border-glow); font-size: 1.4rem; font-weight: 700;
            display: flex; align-items: center; gap: 12px;
        }
        .system-status {
            display: flex; align-items: center; gap: 15px;
        }
        .status-indicator {
            display: flex; align-items: center; gap: 8px; padding: 8px 12px;
            background: var(--glass-strong); border: 1px solid var(--border);
            border-radius: var(--radius-sm); font-size: 0.85rem; font-weight: 600;
        }
        .status-dot { width: 8px; height: 8px; border-radius: 50%; }
        .status-init .status-dot { background: var(--text-muted); animation: pulse 2s infinite; }
        .status-processing .status-dot { background: #fbbf24; animation: pulse 1s infinite; }
        .status-quantum .status-dot { background: var(--primary); animation: pulse 0.8s infinite; }
        .status-complete .status-dot { background: var(--secondary); }
        .status-error .status-dot { background: #ef4444; animation: pulse 1.5s infinite; }
        .content-area {
            flex: 1; display: flex; flex-direction: column; overflow: hidden;
            padding: 20px; gap: 20px;
        }
        .glass-card {
            background: var(--glass); border: 1px solid var(--border);
            border-radius: var(--radius-lg); padding: 24px;
            backdrop-filter: blur(20px) saturate(180%);
        }
        .input-interface {
            display: grid; grid-template-columns: 1fr 1fr; gap: 20px;
        }
        .input-section h3 {
            margin-bottom: 16px; color: var(--text); font-size: 1.2rem;
            display: flex; align-items: center; gap: 10px;
        }
        .sequence-inputs { display: flex; flex-direction: column; gap: 16px; }
        .sequence-group {
            display: flex; flex-direction: column; gap: 8px;
        }
        .sequence-group label {
            font-size: 0.9rem; font-weight: 600; color: var(--text);
            display: flex; align-items: center; gap: 8px;
        }
        .sequence-textarea {
            width: 100%; min-height: 120px; padding: 14px;
            background: var(--glass-strong); border: 1px solid var(--border);
            border-radius: var(--radius-md); color: var(--text);
            font-family: 'SF Mono', 'Cascadia Code', monospace;
            font-size: 0.9rem; resize: vertical;
            transition: all 0.2s var(--transition-curve);
        }
        .sequence-textarea:focus {
            outline: none; border-color: var(--primary);
            box-shadow: 0 0 0 3px rgba(var(--primary-rgb), 0.1);
        }
        .sequence-stats {
            display: flex; justify-content: space-between; gap: 15px;
            font-size: 0.8rem; color: var(--text-muted); margin-top: 8px;
        }
        .parameter-grid {
            display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 16px;
        }
        .param-group { display: flex; flex-direction: column; gap: 8px; }
        .param-group label {
            font-size: 0.9rem; font-weight: 600; color: var(--text);
        }
        .param-input, .param-select {
            padding: 12px 14px; background: var(--glass-strong);
            border: 1px solid var(--border); border-radius: var(--radius-sm);
            color: var(--text); font-family: inherit; font-size: 0.9rem;
            transition: all 0.2s var(--transition-curve);
        }
        .param-input:focus, .param-select:focus {
            outline: none; border-color: var(--primary);
            box-shadow: 0 0 0 3px rgba(var(--primary-rgb), 0.1);
        }
        .upload-area {
            border: 2px dashed var(--border); border-radius: var(--radius-md);
            padding: 30px; text-align: center; cursor: pointer;
            transition: all 0.3s var(--transition-curve);
            background: rgba(0,0,0,0.1);
        }
        .upload-area:hover {
            border-color: var(--primary); background: var(--glass-strong);
        }
        .upload-area i {
            font-size: 2.5rem; color: var(--primary);
            margin-bottom: 12px; display: block;
        }
        .monitoring-grid {
            display: grid; grid-template-columns: 2fr 1fr; gap: 20px;
        }
        .progress-section {
            display: flex; flex-direction: column; gap: 16px;
        }
        .progress-item {
            background: var(--glass-strong); border: 1px solid var(--border);
            border-radius: var(--radius-md); padding: 16px;
        }
        .progress-header {
            display: flex; justify-content: space-between; align-items: center;
            margin-bottom: 12px;
        }
        .progress-title {
            font-weight: 600; font-size: 0.9rem;
        }
        .progress-percentage {
            font-size: 0.85rem; color: var(--primary); font-weight: 600;
        }
        .progress-bar-container {
            height: 8px; background: var(--glass); border-radius: 4px;
            overflow: hidden; position: relative;
        }
        .progress-bar {
            height: 100%; background: linear-gradient(90deg, var(--primary), var(--secondary));
            border-radius: 4px; transition: width 0.5s ease;
        }
        .worker-status {
            display: flex; flex-direction: column; gap: 12px;
        }
        .worker-item {
            display: flex; justify-content: space-between; align-items: center;
            padding: 12px; background: var(--glass-strong);
            border: 1px solid var(--border); border-radius: var(--radius-sm);
        }
        .worker-info {
            display: flex; align-items: center; gap: 10px;
        }
        .worker-dot {
            width: 10px; height: 10px; border-radius: 50%;
        }
        .worker-active .worker-dot {
            background: var(--secondary); animation: pulse 1s infinite;
        }
        .worker-idle .worker-dot {
            background: var(--text-muted);
        }
        .queue-status {
            display: flex; flex-direction: column; gap: 8px;
            padding: 16px; background: var(--glass);
            border: 1px solid var(--border); border-radius: var(--radius-md);
        }
        .results-grid {
            display: grid; grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
            gap: 20px;
        }
        .result-panel {
            background: var(--glass-strong); border: 1px solid var(--border);
            border-radius: var(--radius-md); padding: 20px;
            min-height: 300px; display: flex; flex-direction: column;
        }
        .result-header {
            display: flex; justify-content: space-between; align-items: center;
            margin-bottom: 16px; border-bottom: 1px solid var(--border);
            padding-bottom: 12px;
        }
        .result-title {
            font-weight: 600; font-size: 1rem;
            display: flex; align-items: center; gap: 8px;
        }
        .result-content {
            flex: 1; display: flex; align-items: center;
            justify-content: center; color: var(--text-muted);
            font-style: italic; border: 2px dashed var(--border);
            border-radius: var(--radius-sm); padding: 40px 20px;
        }
        .metrics-table {
            width: 100%; border-collapse: collapse;
        }
        .metrics-table th, .metrics-table td {
            padding: 10px 12px; text-align: left;
            border-bottom: 1px solid var(--border);
        }
        .metrics-table th {
            font-weight: 600; color: var(--text);
            background: var(--glass);
        }
        .metrics-table td {
            color: var(--text-muted);
        }
        .action-buttons {
            display: flex; gap: 12px; justify-content: center;
            flex-wrap: wrap; margin-top: 24px;
        }
        .btn {
            padding: 12px 20px; border-radius: var(--radius-md);
            font-weight: 600; font-size: 0.9rem; cursor: pointer;
            transition: all 0.2s var(--transition-curve);
            display: inline-flex; align-items: center; gap: 8px;
            min-height: 44px; border: 1px solid var(--border);
            text-decoration: none;
        }
        .btn-primary {
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            color: white; border-color: var(--primary);
        }
        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(var(--primary-rgb), 0.4);
        }
        .btn-secondary {
            background: var(--glass-strong); color: var(--text);
        }
        .btn-secondary:hover {
            background: var(--glass-strong); border-color: var(--primary);
            transform: translateY(-1px);
        }
        .log-display {
            background: rgba(0, 0, 0, 0.6); border: 1px solid var(--border);
            border-radius: var(--radius-md); padding: 16px;
            font-family: 'SF Mono', 'Cascadia Code', monospace;
            font-size: 0.85rem; max-height: 300px;
            overflow-y: auto; color: var(--text-muted);
        }
        .log-entry {
            margin-bottom: 4px; display: flex; gap: 10px;
        }
        .log-timestamp {
            color: var(--text-muted); flex-shrink: 0;
        }
        .log-level-info { color: #3b82f6; }
        .log-level-warn { color: #f59e0b; }
        .log-level-error { color: #ef4444; }
        .log-level-success { color: var(--secondary); }
        @media (max-width: 1024px) {
            .input-interface { grid-template-columns: 1fr; }
            .monitoring-grid { grid-template-columns: 1fr; }
            .parameter-grid { grid-template-columns: 1fr; }
        }
        @media (max-width: 768px) {
            .content-area { padding: 16px; }
            .glass-card { padding: 16px; }
            .results-grid { grid-template-columns: 1fr; }
            .action-buttons { flex-direction: column; align-items: stretch; }
        }
        @keyframes spin { to { transform: rotate(360deg); } }
        .loading { animation: spin 1s linear infinite; }
        .hidden { display: none !important; }
        .input-error { border-color: #ef4444 !important; }
        .error-message { color: #ef4444; font-size: 0.8rem; margin-top: 4px; }
    </style>
</head>
<body>
    <div class="aurora-background">
        <div class="aurora one"></div>
        <div class="aurora two"></div>
    </div>
    <div class="container">
        <div class="main-content">
            <header class="header">
                <h1 class="header-title">
                    <i class="fas fa-atom"></i>
                    Kvantum Fehérje Hajtogatási Rendszer
                </h1>
                <div class="system-status">
                    <div class="status-indicator status-init" id="systemStatus">
                        <div class="status-dot"></div>
                        <span id="statusText">Inicializálás</span>
                    </div>
                </div>
            </header>
            <div class="content-area">
                <section class="glass-card">
                    <h2><i class="fas fa-dna"></i> Bemeneti Felület</h2>
                    <div class="input-interface">
                        <div class="input-section">
                            <h3><i class="fas fa-code"></i> Szekvencia Adatok</h3>
                            <div class="sequence-inputs">
                                <div class="sequence-group">
                                    <label for="proteinSequence">
                                        <i class="fas fa-prescription-bottle-alt"></i>
                                        Fehérje Szekvencia (FASTA formátum):
                                    </label>
                                    <textarea id="proteinSequence" class="sequence-textarea" placeholder=">Fehérje_1&#10;&#10;&#10;>Fehérje_2&#10;MKVLILACLVALAALVGSPRRALAYAIGVFVLGLWLAVGLGLGVGSGDGVGVGVGAGAGVGVGAGAGVGVG"></textarea>
                                    <div class="sequence-stats">
                                        <span>Hossz: <span id="proteinLength">0</span> aminosav</span>
                                        <span>Láncok: <span id="proteinChains">0</span></span>
                                        <span>Érvényesség: <span id="proteinValid">Ellenőrzés...</span></span>
                                    </div>
                                </div>
                                <div class="sequence-group">
                                    <label for="dnaSequence">
                                        <i class="fas fa-dna"></i>
                                        DNS Szekvencia (opcionális):
                                    </label>
                                    <textarea id="dnaSequence" class="sequence-textarea" placeholder=">DNS_szekvencia_1&#10;ATGAAGTGGGTAACCTTTATTGCCCCTCTACTACTATTCTCTCTCTCTCTCGCTCTCTCTCTCTCTCTCTCTCTCTCTCTCTCTC"></textarea>
                                    <div class="sequence-stats">
                                        <span>Hossz: <span id="dnaLength">0</span> nukleotid</span>
                                        <span>GC tartalom: <span id="gcContent">0%</span></span>
                                    </div>
                                </div>
                                <div class="sequence-group">
                                    <label for="rnaSequence">
                                        <i class="fas fa-network-wired"></i>
                                        RNS Szekvencia (opcionális):
                                    </label>
                                    <textarea id="rnaSequence" class="sequence-textarea" placeholder=">RNS_szekvencia_1&#10;AUGUGGUACCUUUAUUGCCCCUCUACUACUAUUCUCUCUCUCUCGCUCUCUCUCUCUCUCUCUCUCUCUCUCUCUCUCUC"></textarea>
                                    <div class="sequence-stats">
                                        <span>Hossz: <span id="rnaLength">0</span> nukleotid</span>
                                        <span>AU tartalom: <span id="auContent">0%</span></span>
                                    </div>
                                </div>
                            </div>
                            <div class="sequence-group">
                                <label>
                                    <i class="fas fa-molecule"></i>
                                    Ligand és Molekula Adatok:
                                </label>
                                <div class="upload-area" id="ligandUpload">
                                    <i class="fas fa-cloud-upload-alt"></i>
                                    <div>Kattintson ide vagy húzza ide a fájlokat</div>
                                    <small>Támogatott formátumok: PDB, SDF, MOL2, XYZ</small>
                                </div>
                                <input type="file" id="ligandFileInput" multiple accept=".pdb,.sdf,.mol2,.xyz" style="display: none;">
                                <div id="ligandFileList"></div>
                            </div>
                        </div>
                        <div class="input-section">
                            <h3><i class="fas fa-sliders-h"></i> Paraméterek és Beállítások</h3>
                            <div class="parameter-grid">
                                <div class="param-group">
                                    <label for="numRecycles">
                                        <i class="fas fa-redo"></i>
                                        Újrahasznosítási Ciklusok:
                                    </label>
                                    <input type="number" id="numRecycles" class="param-input" value="10" min="1" max="50">
                                    <small>Ajánlott: 10-20 ciklus</small>
                                </div>
                                <div class="param-group">
                                    <label for="numDiffusionSamples">
                                        <i class="fas fa-wave-square"></i>
                                        Diffúziós Minták:
                                    </label>
                                    <input type="number" id="numDiffusionSamples" class="param-input" value="5" min="1" max="20">
                                    <small>Ajánlott: 5-10 minta</small>
                                </div>
                                <div class="param-group">
                                    <label for="quantumBackend">
                                        <i class="fas fa-microchip"></i>
                                        Kvantum Háttérrendszer:
                                    </label>
                                    <select id="quantumBackend" class="param-select">
                                        <option value="ibm_torino">IBM Quantum Torino</option>
                                        <option value="ibm_brisbane">IBM Quantum Brisbane</option>
                                        <option value="iqm_garnet">IQM Garnet</option>
                                        <option value="ionq_aria">IonQ Aria</option>
                                        <option value="simulator">Klasszikus Szimulátor</option>
                                    </select>
                                </div>
                                <div class="param-group">
                                    <label for="seedValue">
                                        <i class="fas fa-seedling"></i>
                                        Seed Érték (Reprodukálhatóság):
                                    </label>
                                    <input type="number" id="seedValue" class="param-input" placeholder="Véletlenszerű ha üres">
                                </div>
                                <div class="param-group">
                                    <label for="computationLanguage">
                                        <i class="fas fa-code"></i>
                                        Számítási Implementáció:
                                    </label>
                                    <select id="computationLanguage" class="param-select">
                                        <option value="julia">Julia (Ajánlott)</option>
                                        <option value="futhark">Futhark GPU</option>
                                        <option value="hybrid">Hibrid</option>
                                    </select>
                                </div>
                                <div class="param-group">
                                    <label for="maxTemplateDate">
                                        <i class="fas fa-calendar"></i>
                                        Max. Sablon Dátum:
                                    </label>
                                    <input type="date" id="maxTemplateDate" class="param-input" value="2021-09-30">
                                </div>
                            </div>
                        </div>
                    </div>
                    <div class="action-buttons">
                        <button class="btn btn-primary" id="startFolding">
                            <i class="fas fa-play"></i>
                            Hajtogatás Indítása
                        </button>
                        <button class="btn btn-secondary" id="validateInput">
                            <i class="fas fa-check-circle"></i>
                            Bemenet Ellenőrzése
                        </button>
                        <button class="btn btn-secondary" id="loadExample">
                            <i class="fas fa-file-alt"></i>
                            Példa Betöltése
                        </button>
                        <button class="btn btn-secondary" id="resetForm">
                            <i class="fas fa-times"></i>
                            Űrlap Törlése
                        </button>
                    </div>
                </section>
                <section class="glass-card" id="monitoringSection" style="display: none;">
                    <h2><i class="fas fa-chart-line"></i> Folyamat Monitorozás</h2>
                    <div class="monitoring-grid">
                        <div class="progress-section">
                            <div class="progress-item">
                                <div class="progress-header">
                                    <span class="progress-title">Teljes Előrehaladás</span>
                                    <span class="progress-percentage" id="overallProgress">0%</span>
                                </div>
                                <div class="progress-bar-container">
                                    <div class="progress-bar" id="overallProgressBar" style="width: 0%"></div>
                                </div>
                            </div>
                            <div class="progress-item">
                                <div class="progress-header">
                                    <span class="progress-title">Szekvencia Előkészítés</span>
                                    <span class="progress-percentage" id="sequenceProgress">0%</span>
                                </div>
                                <div class="progress-bar-container">
                                    <div class="progress-bar" id="sequenceProgressBar" style="width: 0%"></div>
                                </div>
                            </div>
                            <div class="progress-item">
                                <div class="progress-header">
                                    <span class="progress-title">MSA Generálás</span>
                                    <span class="progress-percentage" id="msaProgress">0%</span>
                                </div>
                                <div class="progress-bar-container">
                                    <div class="progress-bar" id="msaProgressBar" style="width: 0%"></div>
                                </div>
                            </div>
                            <div class="progress-item">
                                <div class="progress-header">
                                    <span class="progress-title">Kvantum Számítás</span>
                                    <span class="progress-percentage" id="quantumProgress">0%</span>
                                </div>
                                <div class="progress-bar-container">
                                    <div class="progress-bar" id="quantumProgressBar" style="width: 0%"></div>
                                </div>
                            </div>
                            <div class="progress-item">
                                <div class="progress-header">
                                    <span class="progress-title">Modell Inferencia</span>
                                    <span class="progress-percentage" id="inferenceProgress">0%</span>
                                </div>
                                <div class="progress-bar-container">
                                    <div class="progress-bar" id="inferenceProgressBar" style="width: 0%"></div>
                                </div>
                            </div>
                        </div>
                        <div class="worker-status">
                            <h4><i class="fas fa-users"></i> Elosztott Rendszer Munkások</h4>
                            <div class="worker-item worker-active">
                                <div class="worker-info">
                                    <div class="worker-dot"></div>
                                    <span>Fő Munkás</span>
                                </div>
                                <span id="mainWorkerStatus">Aktív</span>
                            </div>
                            <div class="worker-item worker-idle">
                                <div class="worker-info">
                                    <div class="worker-dot"></div>
                                    <span>MSA Munkás</span>
                                </div>
                                <span id="msaWorkerStatus">Várakozik</span>
                            </div>
                            <div class="worker-item worker-idle">
                                <div class="worker-info">
                                    <div class="worker-dot"></div>
                                    <span>Kvantum Munkás</span>
                                </div>
                                <span id="quantumWorkerStatus">Várakozik</span>
                            </div>
                            <div class="worker-item worker-idle">
                                <div class="worker-info">
                                    <div class="worker-dot"></div>
                                    <span>Post-Processing</span>
                                </div>
                                <span id="postWorkerStatus">Várakozik</span>
                            </div>
