    <script>
        let appState = {
            isProcessing: false,
            currentStep: 'init',
            jobId: null,
            startTime: null,
            websocket: null,
            results: null
        };
        const elements = {
            systemStatus: document.getElementById('systemStatus'),
            statusText: document.getElementById('statusText'),
            proteinSequence: document.getElementById('proteinSequence'),
            dnaSequence: document.getElementById('dnaSequence'),
            rnaSequence: document.getElementById('rnaSequence'),
            monitoringSection: document.getElementById('monitoringSection'),
            resultsSection: document.getElementById('resultsSection'),
            systemLogs: document.getElementById('systemLogs'),
            startFolding: document.getElementById('startFolding'),
            validateInput: document.getElementById('validateInput'),
            loadExample: document.getElementById('loadExample'),
            resetForm: document.getElementById('resetForm'),
        };
        document.addEventListener('DOMContentLoaded', function() {
            initializeApp();
            setupEventListeners();
            setupFileUpload();
            setupValidation();
        });
        function initializeApp() {
            updateSystemStatus('init', 'Inicializálás');
            addLogEntry('info', 'Alkalmazás inicializálva');
            loadExampleData();
        }
        function setupEventListeners() {
            elements.startFolding.addEventListener('click', startFoldingProcess);
            elements.validateInput.addEventListener('click', validateAllInputs);
            elements.loadExample.addEventListener('click', loadExampleData);
            elements.resetForm.addEventListener('click', resetForm);
            elements.proteinSequence.addEventListener('input', debounce(validateProteinSequence, 500));
            elements.dnaSequence.addEventListener('input', debounce(validateDNASequence, 500));
            elements.rnaSequence.addEventListener('input', debounce(validateRNASequence, 500));
            document.getElementById('downloadPDB')?.addEventListener('click', () => downloadFile('pdb'));
            document.getElementById('downloadJSON')?.addEventListener('click', () => downloadFile('json'));
            document.getElementById('downloadImages')?.addEventListener('click', () => downloadFile('images'));
            document.getElementById('downloadReport')?.addEventListener('click', () => downloadFile('report'));
            document.getElementById('downloadAll')?.addEventListener('click', () => downloadFile('all'));
        }
        function setupFileUpload() {
            const uploadArea = document.getElementById('ligandUpload');
            const fileInput = document.getElementById('ligandFileInput');
            uploadArea.addEventListener('click', () => fileInput.click());
            uploadArea.addEventListener('dragover', handleDragOver);
            uploadArea.addEventListener('drop', handleDrop);
            fileInput.addEventListener('change', handleFileSelect);
        }
        function setupValidation() {
            const inputs = document.querySelectorAll('input, textarea, select');
            inputs.forEach(input => {
                input.addEventListener('blur', () => validateField(input));
            });
        }
        function startFoldingProcess() {
            if (appState.isProcessing) {
                addLogEntry('warn', 'Folyamat már futik!');
                return;
            }
            if (!validateAllInputs()) {
                addLogEntry('error', 'Bemeneti adatok validációja sikertelen!');
                return;
            }
            appState.isProcessing = true;
            appState.startTime = new Date();
            appState.jobId = generateJobId();
            updateSystemStatus('processing', 'Feldolgozás');
            elements.monitoringSection.style.display = 'block';
            elements.startFolding.disabled = true;
            addLogEntry('info', `Kvantum fehérje hajtogatás elkezdve - Job ID: ${appState.jobId}`);
            simulateFoldingProcess();
        }
        function simulateFoldingProcess() {
            const steps = [
                { name: 'sequence', duration: 2000, label: 'Szekvencia Előkészítés' },
                { name: 'msa', duration: 8000, label: 'MSA Generálás' },
                { name: 'quantum', duration: 15000, label: 'Kvantum Számítás' },
                { name: 'inference', duration: 10000, label: 'Modell Inferencia' }
            ];
            let currentStepIndex = 0;
            let currentProgress = 0;
            function processStep() {
                const step = steps[currentStepIndex];
                const stepDuration = step.duration;
                const stepIncrement = 100 / (stepDuration / 100);
                updateSystemStatus('processing', step.label);
                updateWorkerStatus(step.name, 'Aktív');
                const stepInterval = setInterval(() => {
                    currentProgress += stepIncrement;
                    if (currentProgress >= 100) {
                        currentProgress = 100;
                        clearInterval(stepInterval);
                        updateProgressBar(step.name, 100);
                        updateWorkerStatus(step.name, 'Kész');
                        currentStepIndex++;
                        if (currentStepIndex < steps.length) {
                            setTimeout(processStep, 500);
                        } else {
                            completeProcess();
                        }
                    } else {
                        updateProgressBar(step.name, currentProgress);
                    }
                    const overallProgress = (currentStepIndex * 100 + currentProgress) / steps.length;
                    updateProgressBar('overall', overallProgress);
                }, 100);
                addLogEntry('info', `${step.label} elkezdve`);
            }
            processStep();
        }
        function completeProcess() {
            updateSystemStatus('complete', 'Befejezve');
            elements.resultsSection.style.display = 'block';
            appState.isProcessing = false;
            elements.startFolding.disabled = false;
            addLogEntry('success', 'Kvantum fehérje hajtogatás sikeresen befejezve!');
            generateMockResults();
        }
        function generateMockResults() {
            document.getElementById('totalEnergy').textContent = '-12847.2';
            document.getElementById('bondEnergy').textContent = '-8234.1';
            document.getElementById('vdwEnergy').textContent = '-3420.8';
            document.getElementById('electroEnergy').textContent = '-1192.3';
            document.getElementById('avgPlddt').textContent = '87.4';
            document.getElementById('avgPae').textContent = '3.2';
            document.getElementById('tmScore').textContent = '0.821';
            document.getElementById('rmsd').textContent = '1.84';
            const seqLength = elements.proteinSequence.value.replace(/[^A-Z]/g, '').length;
            document.getElementById('metaSeqLength').textContent = seqLength;
            document.getElementById('metaAvgConf').textContent = '85.7%';
            document.getElementById('metaCompTime').textContent = formatTime(Date.now() - appState.startTime);
            document.getElementById('metaBackend').textContent = document.getElementById('quantumBackend').value;
            document.getElementById('metaSeed').textContent = document.getElementById('seedValue').value || 'Véletlenszerű';
            document.getElementById('metaTimestamp').textContent = new Date().toLocaleString('hu-HU');
            document.getElementById('arendVerif').textContent = '✅ Igazolt';
            document.getElementById('coqVerif').textContent = '✅ Igazolt';
            document.getElementById('isabelleVerif').textContent = '✅ Igazolt';
            document.getElementById('tlaVerif').textContent = '✅ Igazolt';
            document.getElementById('formalVerif').textContent = '✅ Minden ellenőrzés sikeres';
        }
        function updateSystemStatus(status, text) {
            appState.currentStep = status;
            elements.statusText.textContent = text;
            elements.systemStatus.className = `status-indicator status-${status}`;
        }
        function updateProgressBar(type, percentage) {
            const progressBar = document.getElementById(`${type}ProgressBar`);
            const progressText = document.getElementById(`${type}Progress`);
            if (progressBar) progressBar.style.width = `${percentage}%`;
            if (progressText) progressText.textContent = `${Math.round(percentage)}%`;
        }
        function updateWorkerStatus(worker, status) {
            const statusElement = document.getElementById(`${worker}WorkerStatus`);
            if (statusElement) {
                statusElement.textContent = status;
                const workerItem = statusElement.closest('.worker-item');
                if (status === 'Aktív') {
                    workerItem.classList.remove('worker-idle');
                    workerItem.classList.add('worker-active');
                } else {
                    workerItem.classList.remove('worker-active');
                    workerItem.classList.add('worker-idle');
                }
            }
        }
        function validateAllInputs() {
            let isValid = true;
            const proteinSeq = elements.proteinSequence.value.trim();
            if (!proteinSeq) {
                showError('proteinSequence', 'Fehérje szekvencia megadása kötelező');
                isValid = false;
            } else if (!validateProteinSequence()) {
                isValid = false;
            }
            const numRecycles = document.getElementById('numRecycles').value;
            if (numRecycles < 1 || numRecycles > 50) {
                showError('numRecycles', 'Az újrahasznosítási ciklusok száma 1 és 50 között kell lennie');
                isValid = false;
            }
            return isValid;
        }
        function validateProteinSequence() {
            const sequence = elements.proteinSequence.value.replace(/[^A-Z]/g, '');
            const validAA = 'ACDEFGHIKLMNPQRSTVWY';
            let isValid = true;
            for (let char of sequence) {
                if (!validAA.includes(char)) {
                    isValid = false;
                    break;
                }
            }
            document.getElementById('proteinLength').textContent = sequence.length;
            document.getElementById('proteinChains').textContent = (elements.proteinSequence.value.match(/>/g) || []).length;
            document.getElementById('proteinValid').textContent = isValid ? '✅ Érvényes' : '❌ Érvénytelen';
            if (!isValid) {
                showError('proteinSequence', 'Érvénytelen aminosav karakterek a szekvenciában');
            } else {
                clearError('proteinSequence');
            }
            return isValid;
        }
        function validateDNASequence() {
            const sequence = elements.dnaSequence.value.replace(/[^ATCG]/g, '');
            const gcCount = (sequence.match(/[GC]/g) || []).length;
            const gcContent = sequence.length > 0 ? Math.round((gcCount / sequence.length) * 100) : 0;
            document.getElementById('dnaLength').textContent = sequence.length;
            document.getElementById('gcContent').textContent = `${gcContent}%`;
            return true;
        }
        function validateRNASequence() {
            const sequence = elements.rnaSequence.value.replace(/[^AUCG]/g, '');
            const auCount = (sequence.match(/[AU]/g) || []).length;
            const auContent = sequence.length > 0 ? Math.round((auCount / sequence.length) * 100) : 0;
            document.getElementById('rnaLength').textContent = sequence.length;
            document.getElementById('auContent').textContent = `${auContent}%`;
            return true;
        }
        function showError(elementId, message) {
            const element = document.getElementById(elementId);
            element.classList.add('input-error');
            let errorDiv = element.parentNode.querySelector('.error-message');
            if (!errorDiv) {
                errorDiv = document.createElement('div');
                errorDiv.className = 'error-message';
                element.parentNode.appendChild(errorDiv);
            }
            errorDiv.textContent = message;
        }
        function clearError(elementId) {
            const element = document.getElementById(elementId);
            element.classList.remove('input-error');
            const errorDiv = element.parentNode.querySelector('.error-message');
            if (errorDiv) {
                errorDiv.remove();
            }
        }
        function loadExampleData() {
            elements.proteinSequence.value = `>Példa_Fehérje_1\`;
            validateProteinSequence();
            addLogEntry('info', 'Példa adatok betöltve');
        }
        function resetForm() {
            const inputs = document.querySelectorAll('input, textarea, select');
            inputs.forEach(input => {
                if (input.type === 'number') {
                    input.value = input.getAttribute('value') || '';
                } else if (input.type === 'date') {
                    input.value = input.getAttribute('value') || '';
                } else if (input.tagName === 'SELECT') {
                    input.selectedIndex = 0;
                } else {
                    input.value = '';
                }
                clearError(input.id);
            });
            document.getElementById('proteinLength').textContent = '0';
            document.getElementById('proteinChains').textContent = '0';
            document.getElementById('proteinValid').textContent = 'Ellenőrzés...';
            document.getElementById('dnaLength').textContent = '0';
            document.getElementById('gcContent').textContent = '0%';
            document.getElementById('rnaLength').textContent = '0';
            document.getElementById('auContent').textContent = '0%';
            elements.monitoringSection.style.display = 'none';
            elements.resultsSection.style.display = 'none';
            updateSystemStatus('init', 'Inicializálás');
            addLogEntry('info', 'Űrlap visszaállítva');
        }
        function handleFileSelect(event) {
            const files = Array.from(event.target.files);
            handleFiles(files);
        }
        function handleDragOver(event) {
            event.preventDefault();
            event.currentTarget.style.borderColor = 'var(--primary)';
        }
        function handleDrop(event) {
            event.preventDefault();
            event.currentTarget.style.borderColor = 'var(--border)';
            const files = Array.from(event.dataTransfer.files);
            handleFiles(files);
        }
        function handleFiles(files) {
            const fileList = document.getElementById('ligandFileList');
            fileList.innerHTML = '';
            files.forEach(file => {
                const fileDiv = document.createElement('div');
                fileDiv.style.cssText = 'margin-top: 8px; padding: 8px; background: var(--glass-strong); border-radius: var(--radius-sm); display: flex; justify-content: space-between; align-items: center;';
                fileDiv.innerHTML = `
                    <span><i class="fas fa-file"></i> ${file.name} (${formatFileSize(file.size)})</span>
                    <button onclick="this.parentElement.remove()" style="background: #ef4444; color: white; border: none; border-radius: 50%; width: 20px; height: 20px; cursor: pointer;">×</button>
                `;
                fileList.appendChild(fileDiv);
            });
            addLogEntry('info', `${files.length} fájl feltöltve`);
        }
        function downloadFile(type) {
            addLogEntry('info', `${type} fájl letöltése megkezdve`);
            const link = document.createElement('a');
            link.href = '#';
            link.download = `protein_folding_${appState.jobId}_${type}.${getFileExtension(type)}`;
            console.log(`Downloading ${type} file...`);
        }
        function getFileExtension(type) {
            const extensions = {
                'pdb': 'pdb',
                'json': 'json',
                'images': 'zip',
                'report': 'pdf',
                'all': 'zip'
            };
            return extensions[type] || 'txt';
        }
        function addLogEntry(level, message) {
            const timestamp = new Date().toLocaleTimeString('hu-HU');
            const logEntry = document.createElement('div');
            logEntry.className = 'log-entry';
            logEntry.innerHTML = `
                <span class="log-timestamp">[${timestamp}]</span>
                <span class="log-level-${level}">[${level.toUpperCase()}]</span>
                <span>${message}</span>
            `;
            elements.systemLogs.appendChild(logEntry);
            elements.systemLogs.scrollTop = elements.systemLogs.scrollHeight;
        }
        function debounce(func, wait) {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        }
        function generateJobId() {
            return 'QF_' + Math.random().toString(36).substr(2, 9).toUpperCase();
        }
        function formatTime(milliseconds) {
            const seconds = Math.floor(milliseconds / 1000);
            const minutes = Math.floor(seconds / 60);
            const hours = Math.floor(minutes / 60);
            if (hours > 0) {
                return `${hours}h ${minutes % 60}m ${seconds % 60}s`;
            } else if (minutes > 0) {
                return `${minutes}m ${seconds % 60}s`;
            } else {
                return `${seconds}s`;
            }
        }
        function formatFileSize(bytes) {
            if (bytes === 0) return '0 Bytes';
            const k = 1024;
            const sizes = ['Bytes', 'KB', 'MB', 'GB'];
            const i = Math.floor(Math.log(bytes) / Math.log(k));
            return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
        }
        function validateField(field) {
            return true;
        }
        function connectToBackend() {
            console.log('Connecting to Julia quantum protein folding backend...');
        }
